#!/usr/bin/env python3
import datetime
import gzip
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP

FACTORS = {
    "kg": Decimal(1),
    "g": Decimal("0.001"),
    "lb": Decimal("0.45392"),
    "oz": Decimal("0.02837"),
}
UNITS = set(FACTORS)
DEPOT_ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"]

DELIMITERS = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
}
FIELDS = {
    "east": ("id", "type", "shipped", "status"),
    "lakeside": ("id", "kind", "shipped", "status"),
    "harbor": ("ref", "rec", "date", "state"),
    "river": ("ref", "t", "shipped", "status"),
    "west": ("id", "typ", "shipped", "status"),
}
BASE_DATE = {"east": "ymd", "lakeside": "ymd", "harbor": "ymd", "river": "mdy", "west": "dmy"}
BASE_UNIT = {"east": "kg", "lakeside": "kg", "harbor": "kg", "river": "kg", "west": "kg"}
TYPE_MAP = {
    "n": "new", "new": "new", "": "new",
    "c": "correction", "cor": "correction", "corr": "correction",
    "correction": "correction", "amend": "correction",
    "v": "void", "void": "void",
}
HARBOR_STATES = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                 "RET": "returned", "HLD": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}


def read_bytes(path):
    with open(path, "rb") as handle:
        data = handle.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data


def decode(data):
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8", "replace")
    if data[:2] == b"\xff\xfe":
        return data[2:].decode("utf-16-le", "replace")
    if data[:2] == b"\xfe\xff":
        return data[2:].decode("utf-16-be", "replace")
    match = re.search(rb"^#[ \t]*charset[ \t]*:[ \t]*([\w.:-]+)", data[:4096], re.M | re.I)
    encoding = "utf-8"
    if match:
        encoding = match.group(1).decode("ascii")
        try:
            "".encode(encoding)
        except LookupError:
            encoding = "utf-8"
    return data.decode(encoding, "replace")


def norm_status(value):
    return re.sub(r"[\s_-]+", "_", (value or "").strip().lower())


def shipment_number(value):
    digits = re.sub(r"\D", "", value or "")
    return int(digits) if digits else None


def norm_unit(value):
    match = re.match(r"\s*([A-Za-z]+)", value or "")
    if match and match.group(1).lower() in UNITS:
        return match.group(1).lower()
    return None


def norm_date_form(value):
    text = (value or "").strip().lower()
    if "serial" in text:
        return "serial"
    if text in ("iso", "ymd", "yyyy-mm-dd", "yyyy/mm/dd"):
        return "ymd"
    if text in ("dmy", "dd-mm-yyyy", "dd/mm/yyyy", "dd.mm.yyyy"):
        return "dmy"
    if text in ("mdy", "mm/dd/yyyy", "mm-dd-yyyy"):
        return "mdy"
    return None


def parse_weight(text, unit, decimal_comma=False):
    text = (text or "").strip()
    if not text:
        return None
    match = re.match(r"^([-+]?[\d.,\s]*\d)\s*([A-Za-z]+)?$", text)
    if not match:
        return None
    number, suffix = match.group(1), match.group(2)
    if suffix:
        if suffix.lower() not in UNITS:
            return None
        unit = suffix.lower()
    number = re.sub(r"\s", "", number)
    if decimal_comma:
        number = number.replace(".", "").replace(",", ".")
    else:
        number = number.replace(",", "")
    return Decimal(number) * FACTORS[unit]


def parse_time(text, form):
    text = (text or "").strip()
    if not text:
        return None
    if form == "serial" and re.fullmatch(r"\d+(\.\d+)?", text):
        return datetime.date(1899, 12, 30) + datetime.timedelta(days=int(float(text)))
    if re.search(r"\d[T ]\d", text) and re.match(r"\d{4}-\d\d-\d\d", text):
        value = datetime.datetime.fromisoformat(text.replace(" ", "T", 1))
        if value.tzinfo is not None:
            value = value.astimezone(datetime.timezone.utc)
        return value.date()
    match = re.fullmatch(r"(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?\s+(\d{4})", text)
    if match:
        return datetime.date(int(match.group(3)), MONTHS.index(match.group(2).lower()) + 1,
                             int(match.group(1)))
    parts = [int(part) for part in re.findall(r"\d+", text)]
    if len(parts) != 3:
        return None
    if form == "dmy":
        day, month, year = parts
    elif form == "mdy":
        month, day, year = parts
    elif parts[0] > 31:
        year, month, day = parts
    elif form == "ymd":
        year, month, day = parts
    else:
        return None
    return datetime.date(year, month, day)


def tokenize(text, delimiter, quoting):
    """Yield ('comment', line) or ('row', fields)."""
    length = len(text)
    pos = 0
    while pos < length:
        if text[pos] == "#":
            end = text.find("\n", pos)
            end = length if end < 0 else end
            yield "comment", text[pos:end].rstrip("\r")
            pos = end + 1
            continue
        fields = []
        field = []
        in_quotes = False
        started = False
        while pos < length:
            char = text[pos]
            if in_quotes:
                if char == '"':
                    if pos + 1 < length and text[pos + 1] == '"':
                        field.append('"')
                        pos += 1
                    else:
                        in_quotes = False
                else:
                    field.append(char)
            elif char == '"' and quoting and not field:
                in_quotes = True
                started = True
            elif char == delimiter:
                fields.append("".join(field))
                field = []
            elif char == "\n":
                pos += 1
                break
            else:
                field.append(char)
            pos += 1
        fields.append("".join(field))
        if fields[-1].endswith("\r") and not started:
            fields[-1] = fields[-1][:-1]
        if len(fields) == 1 and not fields[0].strip() and not started:
            continue
        yield "row", [item.strip() if not quoting else item.strip() for item in fields]


def parse_delimited(depot, text):
    delimiter = DELIMITERS[depot]
    columns = COLUMNS[depot]
    seq = None
    date_form = BASE_DATE[depot]
    unit = BASE_UNIT[depot]
    header = None
    records = []
    id_key, type_key, date_key, status_key = FIELDS[depot]
    decimal_comma = depot == "west"
    for kind, payload in tokenize(text, delimiter, depot in ("east", "lakeside")):
        if kind == "comment":
            harbor = re.match(r"#\s*harbor export\s+seq\s*=\s*(\d+)", payload, re.I)
            if harbor and seq is None:
                seq = int(harbor.group(1))
            directive = re.match(r"#\s*([A-Za-z][A-Za-z ]*?)\s*:\s*(.*)$", payload)
            if not directive:
                continue
            name = directive.group(1).lower()
            value = directive.group(2).strip()
            if name == "seq":
                if seq is None and re.match(r"\d+", value):
                    seq = int(re.match(r"\d+", value).group(0))
            elif name in ("dates", "date format", "date"):
                form = norm_date_form(value)
                if form:
                    date_form = form
            elif name in ("unit", "weight unit"):
                found = norm_unit(value)
                if found:
                    unit = found
            continue
        fields = payload
        lowered = [item.lower() for item in fields]
        if all(item in columns or re.fullmatch(r"(gross|net|weight)_(kg|g|lb|oz)", item)
               for item in lowered):
            header = lowered
            continue
        if header is None or any(item.upper() == "TOTAL" for item in fields):
            continue
        weight_index = next((index for index, name in enumerate(header)
                             if name in ("gross", "weight") or name.startswith("gross_")
                             or name.startswith("weight_")), None)
        row_unit = None
        if len(fields) == len(header) + 1 and weight_index is not None:
            candidate = fields[weight_index + 1].lower()
            if candidate in UNITS:
                row_unit = candidate
                fields = fields[:weight_index + 1] + fields[weight_index + 2:]
        if len(fields) != len(header):
            continue
        row = dict(zip(header, fields))
        number = shipment_number(row.get(id_key))
        if number is None:
            continue
        record_type = TYPE_MAP.get(row.get(type_key, "").strip().lower())
        if record_type is None:
            continue
        record = {"number": number, "type": record_type}
        if record_type != "void":
            weight_unit = row_unit or unit
            weight_text = row.get(header[weight_index]) if weight_index is not None else None
            if weight_index is not None:
                suffix = re.search(r"_(kg|g|lb|oz)$", header[weight_index])
                if suffix:
                    weight_unit = suffix.group(1) if not row_unit else row_unit
            status = row.get(status_key, "")
            if depot == "harbor":
                status = HARBOR_STATES.get(status.strip().upper(), "")
            record["weight"] = parse_weight(weight_text, weight_unit, decimal_comma)
            record["date"] = parse_time(row.get(date_key), date_form)
            record["status"] = norm_status(status)
        records.append(record)
    return seq, records


def parse_north(text):
    seq = None
    records = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            value = json.loads(line)
        except ValueError:
            continue
        items = value if isinstance(value, list) else [value]
        for item in items:
            if not isinstance(item, dict):
                continue
            if "meta" in item and isinstance(item["meta"], dict):
                if seq is None and "seq" in item["meta"]:
                    seq = int(item["meta"]["seq"])
                continue
            number = shipment_number(str(item.get("id", "")))
            if number is None:
                continue
            record_type = TYPE_MAP.get(str(item.get("kind", "new")).strip().lower())
            if record_type is None:
                continue
            record = {"number": number, "type": record_type}
            if record_type != "void":
                weight = None
                for key, value_ in item.items():
                    match = re.fullmatch(r"weight_(kg|g|lb|oz)", key)
                    if match:
                        weight = parse_weight(str(value_), match.group(1))
                if weight is None and "weight" in item:
                    weight = parse_weight(str(item["weight"]), norm_unit(str(item.get("unit"))) or "kg")
                record["weight"] = weight
                record["date"] = parse_time(str(item.get("shipped_at", "")), "ymd")
                record["status"] = norm_status(str(item.get("status", "")))
            records.append(record)
    return seq, records


def parse_central(text):
    text = re.sub(r"^\s*<\?xml[^>]*\?>", "", text)
    root = ET.fromstring(text)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = norm_unit(root.get("weight-unit")) or "kg"
    records = []
    for element in root.iter("shipment"):
        number = shipment_number(element.get("id"))
        if number is None:
            continue
        record_type = TYPE_MAP.get((element.get("type") or "new").strip().lower())
        if record_type is None:
            continue
        record = {"number": number, "type": record_type}
        if record_type != "void":
            weight_element = element.find("weight")
            weight = None
            if weight_element is not None:
                unit = norm_unit(weight_element.get("unit")) or root_unit
                weight = parse_weight(weight_element.text, unit)
            shipped = element.find("shipped")
            shipped_text = shipped.text if shipped is not None else element.get("shipped")
            status = element.find("status")
            record["weight"] = weight
            record["date"] = parse_time(shipped_text, "ymd")
            record["status"] = norm_status(status.text if status is not None else "")
        records.append(record)
    return seq, records


def fw_fields(layout, line):
    if layout == "FW1":
        return line[0:9], line[9], line[10:17], line[17:25], line[25]
    if layout == "FW2":
        return line[1:10], line[0], line[10:18], line[18:26], line[26]
    return line[0:9], line[16], line[9:16], line[17:24], line[24]


def parse_south(text):
    lengths = {"FW1": 42, "FW2": 43, "FW3": 41}
    seq = None
    layout = None
    records = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if "\f" in line or line.startswith("SOUTH DEPOT"):
            continue
        if line.startswith("#"):
            match = re.match(r"#LAYOUT\s+(\w+)", line)
            if match and match.group(1) in lengths:
                layout = match.group(1)
            match = re.match(r"#SEQ\s+(\d+)", line)
            if match and seq is None:
                seq = int(match.group(1))
            continue
        if layout is None or len(line) != lengths[layout]:
            found = [name for name, size in lengths.items() if size == len(line)]
            if not found:
                continue
            record_layout = found[0]
        else:
            record_layout = layout
        ident, rtype, shipped, weight, status = fw_fields(record_layout, line)
        number = shipment_number(ident)
        record_type = TYPE_MAP.get(rtype.strip().lower()) if rtype.strip() else None
        if number is None or record_type is None:
            continue
        record = {"number": number, "type": record_type}
        if record_type != "void":
            if record_layout == "FW1":
                kilos = Decimal(int(weight)) * FACTORS["g"]
            elif record_layout == "FW2":
                kilos = Decimal(int(weight)) / 100
            else:
                kilos = Decimal(int(weight)) / 10 * FACTORS["lb"]
            if record_layout == "FW2":
                date = datetime.datetime.strptime(shipped, "%Y%m%d").date()
            else:
                date = (datetime.date(int(shipped[:4]), 1, 1)
                        + datetime.timedelta(days=int(shipped[4:7]) - 1))
            record["weight"] = kilos
            record["date"] = date
            record["status"] = norm_status(FW_STATUS.get(status.strip().upper(), ""))
        records.append(record)
    return seq, records


def parse_file(depot, path):
    data = read_bytes(path)
    text = decode(data)
    if depot == "central":
        return parse_central(text)
    if depot == "north":
        return parse_north(text)
    if depot == "south":
        return parse_south(text)
    if depot in DELIMITERS:
        return parse_delimited(depot, text)
    return None, []


def money(value):
    return float(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        exports.setdefault(depot, [])
        try:
            seq, records = parse_file(depot, path)
        except Exception as error:
            sys.stderr.write("warning: cannot read %s: %s\n" % (name, error))
            continue
        exports[depot].append((seq if seq is not None else -1, name, records))

    corrections = 0
    resends = 0
    current = {}
    for depot, files in exports.items():
        state = {}
        for _seq, _name, records in sorted(files, key=lambda item: (item[0], item[1])):
            for record in records:
                number = record["number"]
                if record["type"] == "new":
                    if number in state:
                        resends += 1
                    else:
                        state[number] = record
                elif record["type"] == "correction":
                    state[number] = record
                    corrections += 1
                else:
                    state.pop(number, None)
                    corrections += 1
        current[depot] = state

    order = [d for d in DEPOT_ORDER if d in current]
    order += sorted(d for d in current if d not in DEPOT_ORDER)
    kept = {}
    handovers = 0
    owners = {}
    for depot in order:
        for number in current[depot]:
            owners.setdefault(number, []).append(depot)
    for number, depots in owners.items():
        if len(depots) > 1:
            handovers += 1
        kept[number] = (depots[0], current[depots[0]][number])

    depot_totals = {depot: [0, Decimal(0)] for depot in sorted(exports)}
    month_totals = {}
    for depot, record in kept.values():
        if record.get("status") not in ("delivered", "delivered_late"):
            continue
        if record.get("weight") is None or record.get("date") is None:
